WindowController = class("WindowController", Controller)

function WindowController:ShowWindow()
    if (self.view ~= nil) then
        self.view:OnShow(self);
    end
    uiSystem.Instance:ShowWindow(self.view.name);
end

function WindowController:HideWindow()
    uiSystem.Instance:HideWindow(self.view.name);
end
